15	/// <summary>
16	/// Per-frame debug visualization for BoxColliderComponent and ConvexColliderComponent shapes.
17	/// Creates ephemeral mesh entities each frame that render colored outlines:
18	/// red = active, green = passive, gray = disabled.
19	/// Development only — allocates per-frame (ToArray, transient entities) and is not
20	/// intended for production builds.
21	///
22	/// <para>Reads collider ENTITIES (colliders-as-entities): each collider is its own entity — a
23	/// <c>ColliderTagComponent</c>-tagged shape + its own <c>TransformComponent</c> — and this system
24	/// draws every one from that transform's world pose (box via <c>SATCollision.BoxWorldRect</c>,
25	/// convex via the collider's <c>WorldVertices</c>). It coexists with the editor: this system is the
26	/// global diagnostic (thin outlines for EVERY collider, behind the static flag, selection-unaware);
27	/// the editor draws the SELECTED collider entity's own outline + gives it a gizmo (colliders are
28	/// first-class selectable entities now — the whole-shape proxies retired). In Edit the editor keeps
29	/// the selected convex collider's <c>WorldVertices</c> fresh (<c>ProxySyncSystem</c>), so a selected
30	/// collider's debug outline tracks its vertex edits.</para>
31	/// </summary>
32	public class ColliderDebugSystem : ISystem<GameState>
33	{
34	    public static bool Enabled = false;
35	
36	    private const float DebugLayerDepth = 1f;
37	    private const float LineThickness = 0.5f;
38	
39	    private readonly World _world;
40	    private readonly EntitySet _colliderEntities;
41	    private readonly List<Entity> _debugEntities = [];
42	
43	    public ColliderDebugSystem(World world)
44	    {
45	        _world = world;
46	        _colliderEntities = world.GetEntities()
47	            .With<ColliderTagComponent>()
48	            .With<TransformComponent>()
49	            .AsSet();
50	    }
51	
52	    public bool IsEnabled { get; set; } = true;
53	
54	    public void Update(GameState state)
55	    {
56	        foreach (var entity in _debugEntities)
57	        {
58	            if (entity.IsAlive)
59	                entity.Dispose();
60	        }
61	        _debugEntities.Clear();
62	
63	        if (!IsEnabled || !Enabled) return;
64	
65	        foreach (var entity in _colliderEntities.GetEntities())
66	        {
67	            ref readonly var transform = ref entity.Get<TransformComponent>();
68	
69	            if (entity.Has<BoxColliderComponent>())
70	            {
71	                ref readonly var box = ref entity.Get<BoxColliderComponent>();
72	                CreateBoxOutline(transform, box);
73	            }
74	
75	            if (entity.Has<ConvexColliderComponent>())
76	            {
77	                var convex = entity.Get<ConvexColliderComponent>();
78	                CreateConvexOutline(convex);
79	            }
80	        }
81	    }
82	
83	    private void CreateBoxOutline(in TransformComponent transform, in BoxColliderComponent box)
84	    {
85	        var color = GetDebugColor(box);
86	
87	        // Box pose comes from the collider entity's transform (centered, scaled) — the single
88	        // source is SATCollision.BoxWorldRect, so the outline matches what detection tests.
89	        var rect = SATCollision.BoxWorldRect(box, transform);
90	        var topLeft = new Vector2(rect.Left, rect.Top);
91	        var topRight = new Vector2(rect.Right, rect.Top);
92	        var bottomRight = new Vector2(rect.Right, rect.Bottom);
93	        var bottomLeft = new Vector2(rect.Left, rect.Bottom);
94	
95	        var vertices = new List<VertexPositionColor>();
96	        var indices = new List<int>();
97	        int indexOffset = 0;
98	
99	        LineMeshGenerator.AddLine(vertices, indices, topLeft, topRight, LineThickness, color, ref indexOffset);
100	        LineMeshGenerator.AddLine(vertices, indices, topRight, bottomRight, LineThickness, color, ref indexOffset);
101	        LineMeshGenerator.AddLine(vertices, indices, bottomRight, bottomLeft, LineThickness, color, ref indexOffset);
102	        LineMeshGenerator.AddLine(vertices, indices, bottomLeft, topLeft, LineThickness, color, ref indexOffset);
103	
104	        CreateDebugEntity(vertices, indices);
105	    }
106	
107	    private void CreateConvexOutline(ConvexColliderComponent convex)
108	    {
109	        var color = GetDebugColor(convex);
110	        var verts = convex.WorldVertices;
111	        if (verts == null || verts.Length < 3) return;
112	
113	        var vertices = new List<VertexPositionColor>();
114	        var indices = new List<int>();
115	        int indexOffset = 0;
116	
117	        for (int i = 0; i < verts.Length; i++)
118	        {
119	            var start = verts[i];
120	            var end = verts[(i + 1) % verts.Length];
121	            LineMeshGenerator.AddLine(vertices, indices, start, end, LineThickness, color, ref indexOffset);
122	        }
123	
124	        CreateDebugEntity(vertices, indices);
125	    }
126	
127	    private void CreateDebugEntity(List<VertexPositionColor> vertices, List<int> indices)
128	    {
129	        var entity = _world.CreateEntity();
130	        _debugEntities.Add(entity);
131	
132	        entity.Set(new DrawComponent
133	        {
134	            Type = DrawElementType.Mesh,
135	            Vertices = vertices.ToArray(),
136	            Indices = indices.ToArray(),
137	            PrimitiveType = PrimitiveType.TriangleList,
138	            Target = RenderTargetID.Main,
139	            LayerDepth = DebugLayerDepth
140	        });
141	        entity.Set<VisibleComponent>();
142	    }
143	
144	    private static Color GetDebugColor(IColliderComponent collider)
145	    {
146	        if (!collider.Enabled) return Color.Gray;
147	        return collider.Passive ? Color.Green : Color.Red;
148	    }
149	
150	    public void Dispose()
151	    {
152	        foreach (var entity in _debugEntities)
153	        {
154	            if (entity.IsAlive)
155	                entity.Dispose();
156	        }
157	        _debugEntities.Clear();
158	        _colliderEntities.Dispose();
159	    }
