1	using DefaultEcs;
2	using DefaultEcs.System;
3	using Microsoft.Xna.Framework;
4	using MonoDreams.Component;
5	using MonoDreams.Component.Cursor;
6	using MonoDreams.Component.Draw;
7	using MonoDreams.Renderer;
8	using MonoDreams.State;
9	
10	namespace MonoDreams.System.Cursor;
11	
12	public class CursorPositionSystem(World world, MonoDreams.Component.Camera camera, ViewportManager viewportManager)
13	    : AEntitySetSystem<GameState>(world.GetEntities().With<CursorControllerComponent>().With<CursorInputComponent>().With<TransformComponent>().With<DrawComponent>().AsSet())
14	{
15	    protected override void Update(GameState state, in Entity entity)
16	    {
17	        ref var transform = ref entity.Get<TransformComponent>();
18	        ref var input = ref entity.Get<CursorInputComponent>();
19	        ref var controller = ref entity.Get<CursorControllerComponent>();
20	        ref var draw = ref entity.Get<DrawComponent>();
21	
22	        // First convert screen position to virtual coordinates
23	        var virtualPosition = viewportManager.ScaleMouseToVirtualCoordinates(input.ScreenPosition);
24	
25	        // Track whether the pointer is outside the aspect-fit viewport (letterbox bars or the
26	        // editor shell's chrome margins) so world-space consumers can ignore clicks/scrolls there.
27	        input.OutsideViewport = !virtualPosition.HasValue;
28	
29	        if (virtualPosition.HasValue)
30	        {
31	            // Always calculate world position for systems that need it (e.g., ButtonInteractionSystem)
32	            input.VirtualPosition = virtualPosition.Value;
33	            input.WorldPosition = camera.VirtualScreenToWorld(virtualPosition.Value);
34	
35	            // Set transform.Position based on render target:
36	            // - HUD: use virtual coords (no camera transform for rendering)
37	            // - Main: use world coords (camera transform applied during rendering)
38	            if (draw.Target == RenderTargetID.HUD)
39	            {
40	                transform.Position = virtualPosition.Value + controller.HotSpot;
41	            }
42	            else
43	            {
44	                transform.Position = input.WorldPosition + controller.HotSpot;
45	            }
46	        }
47	        // else: Mouse is outside the viewport (in letterbox/pillarbox area) - keep previous position
48	        // Console.WriteLine($"Mouse: {transform.Position}");
49	
50	        entity.NotifyChanged<CursorInputComponent>();
51	        entity.NotifyChanged<TransformComponent>();
52	    }
53	}
