13	/// <summary>How a captured frame reaches the disk.</summary>
14	public enum CaptureFormat
15	{
16	    /// <summary>
17	    /// One PNG per capture, encoded off the main thread. Small files an agent or a human can open, and
18	    /// the only sensible choice for the occasional verification shot.
19	    ///
20	    /// <para><b>It cannot keep up with the game.</b> Encoding a 1280x720 PNG costs far more than a
21	    /// 16.6ms frame, so a capture at every frame drags the game down to ~15-26 fps and the "video" it
22	    /// produces is of a game running in slow motion. That is what <see cref="Raw"/> exists for.</para>
23	    /// </summary>
