26	    /// <summary>
27	    /// One uncompressed RGBA8888 blob per frame, written SYNCHRONOUSLY, with no encode and no
28	    /// per-pixel conversion — the backbuffer's <c>Color[]</c> is reinterpreted as bytes and memcpy'd
29	    /// out. Sustains ~59.8 fps at 1280x720, which is ~220 MB/s.
30	    ///
31	    /// <para><b>It is a firehose.</b> 1280x720x4 = 3.5 MiB a frame, so a 20-second take is about
32	    /// 4.4 GB. Capture to a scratch directory (<c>MONODREAMS_DEBUG_DIR</c>), assemble, delete. See
33	    /// <c>docs/scene-staging.md</c>.</para>
34	    /// </summary>
35	    Raw,
36	}
37	
38	/// <summary>
39	/// Dumps composited frames to the debug directory. Registered ONLY when the environment asks for it —
40	/// see <see cref="FromEnvironment"/> — because constructing it has side effects (it mkdirs and logs),
41	/// so a shipped run that captures nothing should not be building one.
42	///
43	/// <para>Must run after the final composite (<c>FinalDrawSystem</c>): the backbuffer is what it
44	/// reads.</para>
45	/// </summary>
46	public sealed class ScreenshotCaptureSystem : ISystem<GameState>, IDisposable
47	{
48	    /// <summary>How often the byte total is reported in <see cref="CaptureFormat.Raw"/> — the mode is
49	    /// capable of filling a disk inside a minute, so it says so as it goes.</summary>
50	    private const int RawReportEveryFrames = 120;
51	
52	    private readonly GraphicsDevice _graphicsDevice;
53	    private readonly float _captureIntervalSeconds;
54	    private readonly string _outputDirectory;
55	    private readonly CaptureFormat _format;
56	    private readonly int _maxFrames;
57	
58	    private float _timeSinceLastCapture;
59	    private int _counter;
60	    private bool _pendingSave;
61	    private long _bytesWritten;
62	    private bool _stopped;
63	    /// <summary>Grown to the backbuffer on first use — empty rather than null so the resize test is a
64	    /// length comparison and nothing has to ask whether the buffer exists yet.</summary>
65	    private Color[] _pixelBuffer = [];
66	    private Texture2D? _stagingTexture;
67	
68	    /// <summary>Reused destination for the raw memcpy, so a 60 fps capture allocates nothing per
69	    /// frame.</summary>
70	    private byte[] _rawBytes = [];
71	
72	    public bool IsEnabled { get; set; }
73	
74	    /// <summary>Which format this instance writes — the caller's cue that the annotation and the
75	    /// interval mean different things in each.</summary>
76	    public CaptureFormat Format => _format;
77	
78	    public ScreenshotCaptureSystem(GraphicsDevice graphicsDevice, float captureIntervalSeconds,
79	        string outputDirectory, CaptureFormat format = CaptureFormat.Png, int maxFrames = 0)
80	    {
81	        _graphicsDevice = graphicsDevice;
82	        _captureIntervalSeconds = captureIntervalSeconds;
83	        _outputDirectory = outputDirectory;
84	        _format = format;
85	        _maxFrames = maxFrames;
86	
87	        PlatformServices.Current.CreateDirectory(outputDirectory);
88	        Logger.Info($"ScreenshotCaptureSystem initialized. Format: {format}, " +
89	                    $"interval: {(captureIntervalSeconds <= 0f ? "every frame" : captureIntervalSeconds + "s")}, " +
90	                    $"output: {outputDirectory}" +
91	                    (maxFrames > 0 ? $", stopping after {maxFrames} frames" : ""));
92	        if (format == CaptureFormat.Raw)
93	            Logger.Warning("Raw frame capture is ~3.5 MiB per frame at 1280x720 (~220 MB/s at 60 fps). " +
94	                           "Capture to a scratch dir, assemble with tools/frames-to-gif.py, then delete it.");
95	    }
96	
97	    /// <summary>
98	    /// Builds the capture system the environment asks for, or null when it asks for nothing.
99	    ///
100	    /// <list type="bullet">
101	    ///   <item><c>MONODREAMS_SCREENSHOT=1</c> (or <c>png</c>) — PNGs every 0.5s. The historical
102	    ///   behaviour, unchanged.</item>
103	    ///   <item><c>MONODREAMS_SCREENSHOT=raw</c> — raw RGBA every frame, for 60 fps video.</item>
104	    ///   <item><c>MONODREAMS_SCREENSHOT_INTERVAL=&lt;seconds&gt;</c> — overrides the interval of either
105	    ///   (0 = every frame).</item>
106	    ///   <item><c>MONODREAMS_SCREENSHOT_MAX_FRAMES=&lt;n&gt;</c> — stop after n frames. The safety
107	    ///   valve on raw mode: a forgotten capture fills a disk, and 600 frames is ten seconds.</item>
108	    /// </list>
109	    ///
110	    /// <para>Keeping the whole contract here rather than in each screen is deliberate: it is one
111	    /// environment protocol, and a second reader of it would be a second dialect of it.</para>
112	    /// </summary>
113	    public static ScreenshotCaptureSystem? FromEnvironment(GraphicsDevice graphicsDevice, string outputDirectory)
114	    {
115	        var requested = PlatformServices.Current.GetEnvironmentVariable("MONODREAMS_SCREENSHOT");
116	        if (string.IsNullOrWhiteSpace(requested)) return null;
117	
118	        CaptureFormat format;
119	        switch (requested.Trim().ToLowerInvariant())
120	        {
121	            case "0":
122	            case "off":
123	                return null;
124	            case "1":
125	            case "png":
126	                format = CaptureFormat.Png;
127	                break;
128	            case "raw":
129	            case "rgba":
130	                format = CaptureFormat.Raw;
131	                break;
132	            default:
133	                Logger.Error($"MONODREAMS_SCREENSHOT='{requested}' is not a capture mode — capturing " +
134	                             "nothing. Valid modes: 1 (or png), raw.");
135	                return null;
136	        }
137	
138	        // Raw defaults to EVERY frame: the whole point of the mode is a 60 fps take, and an interval
139	        // would silently make it a slideshow.
140	        var interval = format == CaptureFormat.Raw ? 0f : 0.5f;
141	        var overridden = PlatformServices.Current.GetEnvironmentVariable("MONODREAMS_SCREENSHOT_INTERVAL");
142	        if (!string.IsNullOrWhiteSpace(overridden)
143	            && float.TryParse(overridden, global::System.Globalization.NumberStyles.Float,
144	                global::System.Globalization.CultureInfo.InvariantCulture, out var parsed)
145	            && parsed >= 0f)
146	            interval = parsed;
147	
148	        var maxFrames = 0;
149	        var cap = PlatformServices.Current.GetEnvironmentVariable("MONODREAMS_SCREENSHOT_MAX_FRAMES");
150	        if (!string.IsNullOrWhiteSpace(cap) && int.TryParse(cap, out var parsedCap) && parsedCap > 0)
151	            maxFrames = parsedCap;
152	
153	        return new ScreenshotCaptureSystem(graphicsDevice, interval, outputDirectory, format, maxFrames)
154	        {
155	            IsEnabled = true,
156	        };
157	    }
158	
159	    public void Update(GameState state)
160	    {
161	        if (!IsEnabled || _stopped) return;
162	
163	        _timeSinceLastCapture += state.Time;
164	        if (_timeSinceLastCapture < _captureIntervalSeconds) return;
165	        _timeSinceLastCapture = 0f;
166	
167	        if (_maxFrames > 0 && _counter >= _maxFrames)
168	        {
169	            _stopped = true;
170	            Logger.Info($"Frame capture stopped at the {_maxFrames}-frame cap " +
171	                        $"({_bytesWritten / (1024.0 * 1024.0):0.#} MiB written).");
172	            return;
173	        }
174	
175	        if (_format == CaptureFormat.Raw) { CaptureRaw(state.TotalTime); return; }
176	
177	        if (_pendingSave) return;
178	
179	        var frame = Grab();
180	        var filename = MakeFilename(state.TotalTime);
181	        var filePath = PlatformServices.Current.CombinePath(_outputDirectory, filename);
182	
183	        _pendingSave = true;
184	        // Fire-and-forget: desktop runs this on a thread-pool thread; a single-threaded
185	        // host (WASM) runs it inline. Either way the save is best-effort, off the
186	        // deterministic CaptureNow path.
187	        PlatformServices.Current.RunBackground(() =>
188	        {
189	            try
190	            {
191	                PlatformServices.Current.WriteAllBytes(filePath, frame.png);
192	                Logger.Debug($"Screenshot saved: {filename} (nonBlank={frame.nonBlank}, distinctColors={frame.distinct})");
193	            }
194	            catch (Exception ex)
195	            {
196	                Logger.Error($"Failed to save screenshot: {ex.Message}");
197	            }
198	            finally
199	            {
200	                _pendingSave = false;
201	            }
202	        });
203	    }
204	
205	    /// <summary>
206	    /// Synchronously captures the current backbuffer to a PNG in the output directory
207	    /// and returns whether the frame is non-blank (contains more than one distinct
208	    /// colour). Unlike <see cref="Update"/>, the file is fully written before this
209	    /// method returns, so a headless run can capture a verifiable frame on a chosen
210	    /// game frame and exit immediately afterwards without dropping the save.
211	    /// </summary>
212	    public bool CaptureNow(float gameTime)
213	    {
214	        var frame = Grab();
215	        var filename = MakeFilename(gameTime);
216	        var filePath = PlatformServices.Current.CombinePath(_outputDirectory, filename);
217	
218	        try
219	        {
220	            PlatformServices.Current.WriteAllBytes(filePath, frame.png);
221	            Logger.Info($"Screenshot saved: {filename} (nonBlank={frame.nonBlank}, distinctColors={frame.distinct})");
222	        }
223	        catch (Exception ex)
224	        {
225	            Logger.Error($"Failed to save screenshot: {ex.Message}");
226	            return false;
227	        }
228	
229	        return frame.nonBlank;
230	    }
231	
232	    /// <summary>Optional filename annotation (e.g. camera position/zoom) — evaluated per capture
233	    /// and embedded in the name, so an agent reading the shots can map pixels to world space
234	    /// without reverse-engineering the view. Keep the returned string filename-safe.
235	    ///
236	    /// <para><b>PNG mode only.</b> Raw frame names carry the geometry and the timestamp a video
237	    /// assembler needs and nothing else — an annotation there would be a per-frame parsing hazard for
238	    /// no reader.</para></summary>
239	    public Func<string>? AnnotateFilename { get; set; }
240	
241	    private string MakeFilename(float gameTime)
242	    {
243	        var counter = _counter++;
244	        var timestamp = DateTime.Now.ToString("yyyyMMdd_HHmmss_fff");
245	        var annotation = AnnotateFilename?.Invoke();
246	        var suffix = string.IsNullOrEmpty(annotation) ? "" : $"_{annotation}";
247	        return $"screenshot_{counter:D6}_gt{gameTime:F2}{suffix}_{timestamp}.png";
248	    }
249	
250	    // ── Raw ──────────────────────────────────────────────────────────────────────────────────────
251	
252	    /// <summary>
253	    /// Writes the backbuffer verbatim, on the main thread, in the time a memcpy takes.
254	    ///
255	    /// <para><b>Everything expensive that PNG mode does is skipped, and each omission was measured.</b>
256	    /// No <c>SaveAsPng</c> (the encode that caps PNG mode at ~26 fps); no staging <c>Texture2D</c> and
257	    /// therefore no <c>SetData</c> upload of 3.5 MiB per frame; no distinct-colour <c>HashSet</c> pass
258	    /// over 921,600 pixels. What is left is <c>GetBackBufferData</c>, one reinterpreting memcpy, and the
259	    /// write — and it is SYNCHRONOUS on purpose, because a background write cannot keep up with the
260	    /// producer and a queue of 3.5 MiB buffers is how a capture ends in an OOM rather than a video.</para>
261	    ///
262	    /// <para>The reinterpret is the load-bearing trick: <c>Color</c> is a packed RGBA byte quad, so
263	    /// <c>MemoryMarshal.AsBytes</c> over the pixel span IS the file's contents. A conversion loop over
264	    /// nearly a million pixels costs more than everything else here put together.</para>
265	    /// </summary>
266	    private void CaptureRaw(float gameTime)
267	    {
268	        var pp = _graphicsDevice.PresentationParameters;
269	        var width = pp.BackBufferWidth;
270	        var height = pp.BackBufferHeight;
271	        var pixels = width * height;
272	
273	        if (_pixelBuffer.Length != pixels)
274	        {
275	            _pixelBuffer = new Color[pixels];
276	            _rawBytes = new byte[pixels * 4];
277	        }
278	
279	        _graphicsDevice.GetBackBufferData(_pixelBuffer);
280	        MemoryMarshal.AsBytes(_pixelBuffer.AsSpan(0, pixels)).CopyTo(_rawBytes);
281	
282	        // Geometry and timestamp in the NAME, so the directory is self-describing and needs no manifest
283	        // to fall out of step with it. Milliseconds as an integer rather than a formatted float: a
284	        // decimal separator is culture-dependent and would make the tool's parse machine-specific.
285	        var filename = $"raw_{_counter:D6}_{width}x{height}_{(int)MathF.Round(gameTime * 1000f):D8}.rgba";
286	        var filePath = PlatformServices.Current.CombinePath(_outputDirectory, filename);
287	
288	        try
289	        {
290	            PlatformServices.Current.WriteAllBytes(filePath, _rawBytes);
291	        }
292	        catch (Exception ex)
293	        {
294	            _stopped = true;
295	            Logger.Error($"Raw frame capture stopped: {ex.Message} " +
296	                         $"({_counter} frames, {_bytesWritten / (1024.0 * 1024.0):0.#} MiB written). " +
297	                         "A full disk is the usual cause.");
298	            return;
299	        }
300	
301	        _counter++;
302	        _bytesWritten += _rawBytes.Length;
303	        if (_counter % RawReportEveryFrames == 0)
304	            Logger.Info($"Raw capture: {_counter} frames, {_bytesWritten / (1024.0 * 1024.0):0.#} MiB " +
305	                        $"({width}x{height}).");
306	    }
307	
308	    // ── PNG ──────────────────────────────────────────────────────────────────────────────────────
309	
310	    /// <summary>
311	    /// Reads the backbuffer, encodes it to PNG, and computes a cheap blank/non-blank
312	    /// metric. Must run on the main thread after <c>FinalDrawSystem</c> has composited
313	    /// the frame (GetBackBufferData + SaveAsPng both need the graphics context).
314	    /// </summary>
315	    private (byte[] png, bool nonBlank, int distinct) Grab()
316	    {
317	        var pp = _graphicsDevice.PresentationParameters;
318	        int width = pp.BackBufferWidth;
319	        int height = pp.BackBufferHeight;
320	
321	        // Lazily allocate or resize buffers
322	        if (_pixelBuffer.Length != width * height)
323	        {
324	            _pixelBuffer = new Color[width * height];
325	            _stagingTexture?.Dispose();
326	            _stagingTexture = new Texture2D(_graphicsDevice, width, height);
327	        }
328	        // Raw mode never builds one, so a process that switched modes (or a resize) needs it now.
329	        var staging = _stagingTexture ??= new Texture2D(_graphicsDevice, width, height);
330	
331	        _graphicsDevice.GetBackBufferData(_pixelBuffer);
332	        staging.SetData(_pixelBuffer);
333	
334	        // Cheap blank detection: a frame is non-blank if any pixel differs from the
335	        // first one. We also count distinct colours (capped) so the headless log
336	        // carries a coarse "how much was drawn" signal that a test can assert on.
337	        var nonBlank = false;
338	        var first = _pixelBuffer[0];
339	        var distinct = new HashSet<uint>();
340	        foreach (var c in _pixelBuffer)
341	        {
342	            if (c != first) nonBlank = true;
343	            if (distinct.Count < 256) distinct.Add(c.PackedValue);
344	        }
345	
346	        var pngData = new MemoryStream();
347	        staging.SaveAsPng(pngData, width, height);
348	        var pngBytes = pngData.ToArray();
349	        pngData.Dispose();
350	
351	        return (pngBytes, nonBlank, distinct.Count);
352	    }
353	
354	    public void Dispose()
355	    {
356	        if (_format == CaptureFormat.Raw && _counter > 0)
357	            Logger.Info($"Raw capture finished: {_counter} frames, " +
358	                        $"{_bytesWritten / (1024.0 * 1024.0):0.#} MiB in {_outputDirectory}.");
359	        _stagingTexture?.Dispose();
360	        GC.SuppressFinalize(this);
361	    }
362	}
