19	    /// un-mapped injected <c>ScreenPosition</c> and clobber the injection with
20	    /// <c>OutsideViewport = true</c>) stands down. A real-mouse session leaves it false.
21	    /// </summary>
22	    public bool SkipDerivation { get; set; }
23	
24	    protected override void Update(GameState state, in Entity entity)
25	    {
26	        if (SkipDerivation) return;
27	        ref var transform = ref entity.Get<TransformComponent>();
28	        ref var input = ref entity.Get<CursorInputComponent>();
29	        ref var controller = ref entity.Get<CursorControllerComponent>();
30	        ref var draw = ref entity.Get<DrawComponent>();
31	
32	        // First convert screen position to virtual coordinates
33	        var virtualPosition = viewportManager.ScaleMouseToVirtualCoordinates(input.ScreenPosition);
34	
35	        // Track whether the pointer is outside the aspect-fit viewport (letterbox bars or the
36	        // editor shell's chrome margins) so world-space consumers can ignore clicks/scrolls there.
37	        input.OutsideViewport = !virtualPosition.HasValue;
38	
39	        if (virtualPosition.HasValue)
